steps.script:
AIDecisionMaker.reset_caches()
var d = AIPlayer.request_suggestion()
var a = d.get("_ai_assignment", {})
var rec = false
for r in d.get("_ai_decision_records", []):
	if str(r.get("decision_type", "")) == "forecast_plan":
		rec = true
return "%s|%s|%s|%s|%s|%s" % [d.get("type", ""), d.get("actor_unit_id", ""), a.get("objective_id", ""), a.get("assign_pass", ""), str(str(d.get("_ai_description", "")).contains("forecast: worth about")), str(rec)]
